eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   mayaData: () => (/* binding */ mayaData)\n/* harmony export */ });\nconst mayaData = {\n    themeName: \"maya\",\n    brandName: \"Dr. Maya Reynolds, PsyD\",\n    subtitle: \"Licensed Clinical Psychologist \\xb7 Santa Monica, CA\",\n    seoTitle: \"Dr. Maya Reynolds, PsyD | Anxiety, Trauma & Burnout Therapy in Santa Monica, CA\",\n    locationLabel: \"Santa Monica, California \\xb7 In-Person & Telehealth\",\n    address: {\n        street: \"\",\n        city: \"Santa Monica\",\n        state: \"CA\",\n        zip: \"\",\n        note: \"\"\n    },\n    servingAreas: \"Serving Santa Monica, Venice, Brentwood, Pacific Palisades & all California\",\n    navItems: [\n        {\n            label: \"About\",\n            href: \"#about\"\n        },\n        {\n            label: \"Modalities\",\n            href: \"#services\"\n        },\n        {\n            label: \"Specialties\",\n            href: \"#expertise\"\n        },\n        {\n            label: \"Office\",\n            href: \"#office\"\n        },\n        {\n            label: \"FAQs\",\n            href: \"/faqs\"\n        }\n    ],\n    hero: {\n        eyebrow: \"A Thoughtful Path Forward\",\n        titleLead: \"A quieter space to understand what you’re carrying and finally begin to\",\n        titleAccent: \"thrive\",\n        titleSuffix: \".\",\n        description: \"Grounded, collaborative therapy for adults navigating anxiety, trauma, burnout, and the pressure to keep going.\",\n        ctaText: \"Schedule a Consultation\",\n        ctaHref: \"#contact\",\n        mainImage: \"/images/download.jpg\",\n        mainImageAlt: \"Warm therapy conversation with a client and clinician\",\n        peekImage: \"/images/bookshelf.jpg\",\n        peekImageAlt: \"A hand selecting a book from a softly lit bookshelf\",\n        caption: \"Licensed Clinical Psychologist \\xb7 California License PSY30219\"\n    },\n    intro: {\n        title: \"You’re holding onto hope that life can feel calmer, lighter, and more grounded than it is right now.\",\n        leadBold: \"In my practice, I help you transform that hope into lasting relief and sustainable well-being.\",\n        col1: \"Whether you’re an adult seeking personal growth, looking to process trauma safely, or trying to manage intense professional burnout, therapy provides a compassionate and confidential space to unpack what feels overwhelming.\",\n        col2: \"What you are experiencing is real, valid, and worthy of care. I help high-achieving individuals reconnect with themselves, release chronic tension, and build a resilient foundation for the future — in person and via telehealth across California.\",\n        image: \"/images/maya/intro-forest-path.jpg\",\n        imageAlt: \"Sunlit forest path symbolizing a journey toward clarity and healing\"\n    },\n    servicesSection: {\n        headingLead: \"Clinical\",\n        headingAccent: \"Modalities\",\n        subtitle: \"Many of my clients appear capable and functional on the outside while quietly carrying anxiety, tension, or chronic emotional fatigue. Here are three primary areas of clinical focus:\",\n        services: [\n            {\n                title: \"Trauma & EMDR\",\n                subtitle: \"Paced, Body-Grounded Processing\",\n                description: \"Carefully paced work for single-incident trauma, childhood emotional wounds, or relationship distress. Using EMDR and body-oriented therapies, I help you feel more secure in the present.\",\n                image: \"/images/maya/4c1fff581f6c3d5e43cd495aee721156.jpg\",\n                alt: \"Therapist speaking with a client in a calm counseling room\",\n                linkText: \"Explore EMDR & Trauma Therapy\",\n                href: \"#contact\"\n            },\n            {\n                title: \"Anxiety & Panic\",\n                subtitle: \"Break Free from Overthinking\",\n                description: \"Support for constant worry, internal tension, sleeplessness, and the exhausting sensation of always bracing for something to go wrong. I combine CBT and nervous system regulation to help you regain clarity and ease.\",\n                image: \"/images/maya/b2d5db3b677faa320bacfee66be22920.jpg\",\n                alt: \"Woman at a desk looking overwhelmed while working through anxiety and emotional pressure\",\n                linkText: \"Learn More About Anxiety Care\",\n                href: \"#contact\"\n            },\n            {\n                title: \"Burnout & Pressure\",\n                subtitle: \"For High-Achievers & Creatives\",\n                description: \"Support for when perfectionism, intense expectations, and years of overextending have left you feeling empty. We work on building sustainable limits and finding meaning that exists beyond your output.\",\n                image: \"/images/maya/a778f50bc2fe59d3c06da672d064a41b.jpg\",\n                alt: \"Adult in a calm telehealth session\",\n                linkText: \"Support for burnout & perfectionism\",\n                href: \"#contact\"\n            }\n        ]\n    },\n    banner: {\n        quote: \"You can be capable, accomplished, and still need support.\",\n        emphasis: \"There is no need to have everything figured out before you begin.\",\n        backgroundImage: \"/images/maya/banner-golden-sunset.jpg\"\n    },\n    expertise: {\n        headingLead: \"Areas of\",\n        headingAccent: \"expertise\",\n        groups: [\n            {\n                title: \"Concerns\",\n                items: [\n                    \"Anxiety & Panic Disorders\",\n                    \"Trauma & PTSD Recovery\",\n                    \"Professional Burnout\",\n                    \"Perfectionism & High Pressure\"\n                ]\n            },\n            {\n                title: \"Approaches\",\n                items: [\n                    \"EMDR Therapy\",\n                    \"Cognitive Behavioral Therapy (CBT)\",\n                    \"Mindfulness-Based Practices\",\n                    \"Somatic & Body-Oriented Work\"\n                ]\n            },\n            {\n                title: \"Clients\",\n                items: [\n                    \"Thoughtful Adults\",\n                    \"High-Achieving Adults\",\n                    \"Entrepreneurs & Creatives\"\n                ]\n            }\n        ]\n    },\n    quoteFeature: {\n        image: \"/images/maya/quote-beach.jpg\",\n        imageAlt: \"A soft, warm coastal landscape with quiet hills and a peaceful dusk atmosphere\",\n        quoteLead: \"Honoring where you’ve been\",\n        quoteAccent: \"\",\n        quoteSuffix: \" & helping shape where you’re headed.\"\n    },\n    specialties: {\n        headingLead: \"Clinical\",\n        headingAccent: \"specialties\",\n        headingSuffix: \"include…\",\n        cards: [\n            {\n                title: \"Trauma & PTSD\",\n                description: \"In therapy, I gently help you process traumatic memories, restore a sense of physical safety, and reclaim your autonomy, peace, and confidence.\",\n                href: \"#contact\"\n            },\n            {\n                title: \"Anxiety & Panic\",\n                description: \"I work at the roots of persistent worry to help your nervous system shift from chronic high alert toward lasting calm, clarity, and ease.\",\n                href: \"#contact\"\n            },\n            {\n                title: \"EMDR Therapy\",\n                description: \"EMDR is an evidence-based method that reworks how distressing memories are stored in the body — reducing their emotional charge and supporting lasting relief.\",\n                href: \"#contact\"\n            },\n            {\n                title: \"Burnout & High Pressure\",\n                description: \"Tailored support for those whose identity has become inseparable from their productivity — helping you separate self-worth from output and restore genuine vitality.\",\n                href: \"#contact\"\n            }\n        ]\n    },\n    officeSection: {\n        eyebrow: \"MY SANTA MONICA SPACE\",\n        headingLead: \"A quiet, grounding space for\",\n        headingAccent: \"healing\",\n        headingSuffix: \".\",\n        description: \"A private sanctuary intentionally designed to feel welcoming, calm, and restorative from the moment you arrive. With abundant natural light, comfortable furnishings, and an uncluttered environment, the space itself invites you to exhale, settle, and feel at ease.\",\n        address: \"Santa Monica, California\",\n        sessionTypes: \"In-person sessions in Santa Monica and secure telehealth for clients located anywhere in California.\",\n        features: [\n            \"Quiet & Private Atmosphere\",\n            \"Abundant Natural Sunlight\",\n            \"Comfortable, Uncluttered Design\",\n            \"Convenient Santa Monica Location\",\n            \"Confidential, Grounding Setting\"\n        ],\n        images: [\n            {\n                src: \"/images/office-1.jpg\",\n                alt: \"Santa Monica therapy room with comfortable sofa and warm wooden floors\",\n                caption: \"Comfortable seating & thoughtful ambiance for reflection\"\n            },\n            {\n                src: \"/images/office-2.jpg\",\n                alt: \"Santa Monica counseling office with natural light and private surroundings\",\n                caption: \"Natural light & serene, private surroundings\"\n            }\n        ]\n    },\n    schedule: {\n        eyebrow: \"LET’S CONNECT\",\n        headingLead: \"Take the first step toward finding the right therapist for you.\",\n        headingAccent: \"\",\n        headingSuffix: \"\",\n        body: \"Finding a therapist whose presence, pacing, and approach resonate with you is essential. I offer a complimentary 15-minute introductory phone call to discuss what you are looking for and see if working together feels right.\",\n        instruction: \"\",\n        buttonText: \"Book a Consultation\",\n        buttonHref: \"#contact\"\n    },\n    aboutBio: {\n        eyebrow: \"MEET YOUR THERAPIST\",\n        title: \"Dr. Maya Reynolds, PsyD\",\n        credentials: \"Licensed Clinical Psychologist \\xb7 California License PSY30219\",\n        paragraphs: [\n            \"I’m a licensed clinical psychologist based in Santa Monica, California, offering therapy for adults who feel overwhelmed by anxiety, stress, or the lingering effects of past experiences.\",\n            \"My work focuses on anxiety, panic, trauma, and burnout. Clients often come to me feeling functional on the outside while quietly carrying persistent worry, tension, difficulty sleeping, or a low-level dread they cannot quite name.\",\n            \"I take a warm, collaborative, and grounded approach. I take time to understand your unique life story rather than offering generic advice, and together we identify the patterns that keep you feeling stuck.\",\n            \"Sessions integrate CBT, EMDR, mindfulness-based practices, and body-oriented techniques — designed to give you practical insights and regulation tools you can use in daily life.\"\n        ],\n        quote: \"Good therapy doesn’t just solve problems — it changes the relationship you have with yourself.\"\n    },\n    faqs: [\n        {\n            question: \"Where is your office located, and do you offer in-person sessions?\",\n            answer: \"I offer in-person therapy in Santa Monica and secure telehealth sessions for clients anywhere in California.\"\n        },\n        {\n            question: \"Who do you typically work with?\",\n            answer: \"I primarily support thoughtful, high-achieving adults, entrepreneurs, creatives, and professionals who appear successful on the outside but are internally exhausted by chronic worry, panic, trauma triggers, or perfectionism.\"\n        },\n        {\n            question: \"What is your approach to trauma and EMDR therapy?\",\n            answer: \"Trauma work in my practice is paced carefully with an emphasis on safety, stabilization, and nervous system regulation. I use EMDR alongside CBT and somatic methods to help you process distressing memories at a manageable pace.\"\n        },\n        {\n            question: \"What happens during the initial consultation?\",\n            answer: \"I begin with a complimentary 15-minute phone consultation to discuss what brings you to therapy, answer your questions, and see whether my approach is a good fit for your needs.\"\n        },\n        {\n            question: \"Do you accept insurance?\",\n            answer: \"I am an out-of-network provider. I provide detailed monthly superbills that you can submit to your insurance company for potential PPO reimbursement. Please check with your insurer regarding your benefits.\"\n        }\n    ],\n    footer: {\n        intro: \"Specialized clinical psychology and psychotherapy for adults, high-achievers, and entrepreneurs in Santa Monica and across California via telehealth.\",\n        navLinks: [\n            {\n                label: \"About Dr. Maya\",\n                href: \"#about\"\n            },\n            {\n                label: \"Modalities\",\n                href: \"#services\"\n            },\n            {\n                label: \"Specialties\",\n                href: \"#expertise\"\n            },\n            {\n                label: \"Office\",\n                href: \"#office\"\n            },\n            {\n                label: \"FAQs\",\n                href: \"/faqs\"\n            }\n        ],\n        contactInfo: [\n            \"Santa Monica, California\",\n            \"In-person & telehealth across California\"\n        ],\n        practiceDetails: [\n            \"Dr. Maya Reynolds, PsyD\",\n            \"Licensed Clinical Psychologist\",\n            \"California License PSY30219\",\n            \"By appointment\"\n        ],\n        legal: \"\\xa9 2026 Dr. Maya Reynolds, PsyD. All rights reserved. | Santa Monica, CA\"\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/siteData.ts\n");

